export const VISUALS: readonly GalleryVisual[] = [
  {"slug":"jee-vernier-scale","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"units-and-measurements","chapterName":"Units and Measurements","subtopicSlug":"nph-um-instruments","subtopicTitle":"Vernier Callipers and Screw Gauge","conceptSlug":"nphum-vernier","conceptName":"Vernier calliper: least count and reading","line":"A vernier scale slides along the main scale. Its divisions are made a little shorter than the main scale divisions, so only one vernier line lines up exactly with a main scale line. How far along that line is tells you the fraction of a main scale division that the main scale alone cannot show.","pyqExampleId":"387bb51c-0900-414a-a2b5-deee429ecad5","badge":"picture","interactive":false},
  {"slug":"kin-velocity-time-graph","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"motion-in-a-straight-line","chapterName":"Motion in a Straight Line","subtopicSlug":"nph-ms-graphs","subtopicTitle":"Calculus and Motion Graphs","conceptSlug":"nphms-graphs","conceptName":"Slopes and areas of motion graphs","line":"Every motion graph hides two readings. The slope of a graph tells you the rate of change of what is plotted: the slope of position against time is the velocity, and the slope of velocity against time is the acceleration. The area under a graph adds things up over time: the area under velocity-time is the displacement, and the area under acceleration-time is the change in velocity.","pyqExampleId":"23d6a7e9-d09d-4477-bdd6-c2f149a1d444","badge":"picture","interactive":false},
  {"slug":"kin-projectile-parabola","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"motion-in-a-plane","chapterName":"Motion in a Plane","subtopicSlug":"nph-mp-projectile","subtopicTitle":"Vectors and Projectile Motion","conceptSlug":"nphmp-projectile","conceptName":"Projectile motion: the two parts of the velocity","line":"Once a ball leaves the hand, the only force on it (ignoring air) is its weight, which is vertical. So nothing changes its horizontal velocity: that part stays the same all the way. The vertical part starts upward, falls by g every second, becomes zero at the top and then grows downward. Put the two parts together and the path is a parabola.","pyqExampleId":"8c337d88-e650-4f07-9e93-d1ae897a7bcd","badge":"picture","interactive":false},
  {"slug":"lmf-action-reaction-pair","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"nph-lm-newton","subtopicTitle":"Newton's Laws and Momentum","conceptSlug":"nphlm-newton-laws","conceptName":"Newton's three laws of motion","line":"A body left alone keeps doing what it was doing: resting, or moving straight at a steady speed. To change its velocity you need a net force, and the force points the way the velocity changes, not the way the body is moving. Forces always come in pairs: when you push a wall, the wall pushes you back just as hard.","pyqExampleId":"60595d2a-dfca-470d-bb6b-ac1c7e15c0ca","badge":"picture","interactive":false},
  {"slug":"lmf-free-body-diagram","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"nph-lm-friction","subtopicTitle":"Connected Bodies and Friction","conceptSlug":"nphlm-friction","conceptName":"Static and kinetic friction","line":"Push a heavy box gently and it does not move: the floor pushes back with friction just as hard as you push. Static friction grows with your push only up to a limit. Push past that limit and the box slides, and a slightly smaller kinetic friction then acts on it.","pyqExampleId":"064e5eb4-f135-4dbb-bb0d-e93a7734fae9","badge":"picture","interactive":false},
  {"slug":"imat-circular-motion","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"laws-of-motion","chapterName":"Laws of Motion","subtopicSlug":"nph-lm-circular","subtopicTitle":"Circular Motion","conceptSlug":"nphlm-centripetal","conceptName":"Centripetal force","line":"Even at a steady speed, a body going round a circle keeps changing direction, so it is accelerating toward the centre. Some real force must pull it inward: the string for a whirled stone, friction for a car on a level turn. Centripetal force is not a new kind of force, it is the job one of these forces does.","pyqExampleId":"4475be09-abd5-44aa-96a0-ae40d97570c4","badge":"try","interactive":true},
  {"slug":"wep-work-at-angle","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"work-energy-and-power","chapterName":"Work, Energy and Power","subtopicSlug":"nph-we-work","subtopicTitle":"Work and the Work-Energy Theorem","conceptSlug":"nphwe-work","conceptName":"Work done by a constant and a variable force","line":"A force does work when the body it acts on moves. Only the part of the force along the motion counts: a force at right angles to the motion does no work at all, however large it is. A force that helps the motion does positive work, one that opposes it, like friction, does negative work. When the force changes as the body moves, cut the path into tiny steps, find the work on each, and add them up. That sum is the area under the force-position graph.","pyqExampleId":"113003d8-b1a5-4ef7-b5ba-0f7453795ac2","badge":"picture","interactive":false},
  {"slug":"wep-energy-conservation-track","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"work-energy-and-power","chapterName":"Work, Energy and Power","subtopicSlug":"nph-we-energy","subtopicTitle":"Potential Energy and Conservation","conceptSlug":"nphwe-conservation","conceptName":"Conservation of mechanical energy and the vertical circle","line":"Gravity and springs are conservative forces: the work they do depends only on where a body starts and ends, not on the path. Energy they take as potential energy they give back. So when only they do work, kinetic plus potential energy stays the same. A string pulling a bob round a circle is always at right angles to its motion, so it does no work either, and energy conservation alone gives the bob's speed at any height. The string's tension then tells you whether the bob stays on the circle: when the tension falls to zero, the string goes slack.","pyqExampleId":"fc1b2ac1-a5f6-491a-9a21-c8d0676c2a24","badge":"picture","interactive":false},
  {"slug":"imat-collision-momentum","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"work-energy-and-power","chapterName":"Work, Energy and Power","subtopicSlug":"nph-we-collisions","subtopicTitle":"Collisions","conceptSlug":"nphwe-inelastic","conceptName":"Momentum, kinetic energy and sticking collisions","line":"When two bodies collide, the large forces between them are internal to the pair, equal and opposite. So the total momentum just before and just after the collision is the same, in every kind of collision. Kinetic energy is a different story: some of it usually turns into heat, sound and the bending of the bodies. When the bodies stick together, they move off with one common velocity and the most kinetic energy is lost.","pyqExampleId":"2000c2e6-5d38-43f1-9102-ed26f34864ef","badge":"try","interactive":true},
  {"slug":"torque-moment","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"rotational-motion","chapterName":"System of Particles and Rotational Motion","subtopicSlug":"nph-rm-torque","subtopicTitle":"Torque and Equilibrium","conceptSlug":"nphrm-torque","conceptName":"Torque and the moment of a force","line":"A door opens easily when you push far from the hinges and at right angles to the door. Push near the hinges, or along the door towards them, and nothing turns. Torque measures this turning effect: the force times how far its line of action passes from the turning point.","pyqExampleId":"d459fa62-2f06-4c48-bef1-1f50604a9174","badge":"try","interactive":true},
  {"slug":"imat-moments-seesaw","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"rotational-motion","chapterName":"System of Particles and Rotational Motion","subtopicSlug":"nph-rm-torque","subtopicTitle":"Torque and Equilibrium","conceptSlug":"nphrm-equilibrium","conceptName":"Equilibrium of a rigid body","line":"A body stays at rest only if nothing pushes it along and nothing turns it. So the forces must add to zero and the torques must add to zero. Since the torques add to zero about every point, you are free to take moments about the point where an unknown force acts, and that force drops out.","pyqExampleId":"a8844c65-dbca-4ba7-abb0-029ccc0cfa4f","badge":"try","interactive":true},
  {"slug":"jee-parallel-axis","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"rotational-motion","chapterName":"System of Particles and Rotational Motion","subtopicSlug":"nph-rm-inertia","subtopicTitle":"Moment of Inertia","conceptSlug":"nphrm-axis-theorems","conceptName":"Parallel and perpendicular axis theorems","line":"The table gives I only about axes through the centre. The parallel axis theorem moves the axis sideways: the body now also swings its whole mass round a circle of radius d, which adds \\(Md^{2}\\). The perpendicular axis theorem works only for a flat body: the axis normal to the plane is the sum of two perpendicular axes lying in the plane.","pyqExampleId":"7b7d58cd-113c-4987-81f5-1ffea2596f49","badge":"picture","interactive":false},
  {"slug":"cet-rolling-energy-split","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"rotational-motion","chapterName":"System of Particles and Rotational Motion","subtopicSlug":"nph-rm-rotation","subtopicTitle":"Rotation and Rolling","conceptSlug":"nphrm-rolling","conceptName":"Rolling without slipping","line":"A rolling wheel moves forward and spins at the same time. Without slipping, these two motions cancel exactly where the wheel touches the ground, so that point is at rest for an instant, and they add at the top. Its kinetic energy has two parts too: the motion of the centre and the spin about it.","pyqExampleId":"3e57f7e2-2cd6-4fd4-9a05-0480acba2228","badge":"picture","interactive":false},
  {"slug":"grav-kepler-orbit","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"gravitation","chapterName":"Gravitation","subtopicSlug":"nph-gr-orbits","subtopicTitle":"Kepler's Laws and Satellites","conceptSlug":"nphgr-kepler","conceptName":"Kepler's laws of planetary motion","line":"Kepler found three rules by studying how the planets move. Orbits are ellipses, not perfect circles. A planet speeds up as it swings close to the sun and slows down far away. And planets farther out take much longer to go round, more than the extra distance alone would suggest.","pyqExampleId":"04c5bd75-434f-49c9-9e7d-8e213d402e8a","badge":"picture","interactive":false},
  {"slug":"jee-stress-strain","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"mechanical-properties-of-solids","chapterName":"Mechanical Properties of Solids","subtopicSlug":"nph-so-moduli","subtopicTitle":"Elastic Moduli and Materials","conceptSlug":"nphso-materials","conceptName":"The stress-strain curve and how materials behave","line":"Pull a metal wire harder and harder and plot stress against strain. At first the graph is a straight line and the wire springs back. Past a point it stops springing back fully, then it flows, and at last it breaks. Different materials go through these stages differently, which is why steel is used for springs and girders and rubber for bands.","pyqExampleId":"be50733a-ea81-43a2-b8c7-33aacf433c56","badge":"picture","interactive":false},
  {"slug":"fluid-pressure-depth","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"nph-fl-pressure","subtopicTitle":"Pressure and Fluid Flow","conceptSlug":"nphfl-pressure","conceptName":"Pressure at a depth and Pascal's law","line":"A liquid at rest presses on everything it touches. The deeper you go, the more liquid sits above you, so the pressure grows with depth. On top of that, the air above the liquid presses down too. Pascal noticed something useful: a pressure added at one place in an enclosed liquid reaches every other place equally. That is how a small push on a narrow piston lifts a car on a wide one.","pyqExampleId":"995baa47-8304-46fc-ac6c-a1255ff87122","badge":"picture","interactive":false},
  {"slug":"cet-continuity-pipe","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"nph-fl-pressure","subtopicTitle":"Pressure and Fluid Flow","conceptSlug":"nphfl-continuity","conceptName":"Streamline flow and the equation of continuity","line":"In smooth, steady flow every bit of liquid that passes a point follows the same path, called a streamline. A liquid like water hardly squeezes, so whatever volume enters a pipe each second must leave it each second. Where the pipe is narrow, the same volume has to get through a smaller opening, so the water moves faster.","pyqExampleId":"6dde963b-fef5-4104-8883-846c246b02d7","badge":"try","interactive":true},
  {"slug":"surface-tension-meniscus","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"mechanical-properties-of-fluids","chapterName":"Mechanical Properties of Fluids","subtopicSlug":"nph-fl-surface","subtopicTitle":"Surface Tension and Capillarity","conceptSlug":"nphfl-capillary","conceptName":"Angle of contact and capillary rise","line":"Where a liquid meets a solid, two pulls compete: the liquid's molecules pull on each other, and the solid pulls on the liquid. If the solid wins, the liquid spreads, curves up the wall and climbs a narrow tube. Water on clean glass does this. If the liquid's own pull wins, as for mercury on glass, it curves down and sinks in the tube. The angle at which the surface meets the wall tells you which happened.","pyqExampleId":"aa1589b2-cc36-413f-a404-e3747c87e1ed","badge":"picture","interactive":false},
  {"slug":"ht-anomalous-water-expansion","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"thermal-properties-of-matter","chapterName":"Thermal Properties of Matter","subtopicSlug":"nph-tp-expansion","subtopicTitle":"Expansion and Specific Heat","conceptSlug":"nphtp-expansion","conceptName":"Linear, area and volume expansion","line":"Heat a solid and its particles vibrate more and push each other a little further apart. Every length in the body grows by the same small fraction, αΔT. An area has two lengths in it, so it grows by about twice that fraction; a volume has three, so it grows by about three times. A hole in a plate grows too, exactly as the piece of metal that would fill it.","pyqExampleId":"361f61c6-165b-4d07-9003-8dff5cb7ca88","badge":"picture","interactive":false},
  {"slug":"ht-heat-transfer-modes","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"thermal-properties-of-matter","chapterName":"Thermal Properties of Matter","subtopicSlug":"nph-tp-transfer","subtopicTitle":"Heat Transfer and Cooling","conceptSlug":"nphtp-convection-radiation","conceptName":"Conduction, convection, radiation and insulators","line":"Heat moves in three ways. In conduction it is passed from particle to particle while the material stays in place. In convection the warm fluid itself moves and carries the heat with it. In radiation it travels as electromagnetic waves and needs no medium at all. An insulator works by blocking these paths, and still, trapped air is one of the best.","pyqExampleId":"a904faa3-1b5c-47ae-80dd-aa218c3a91fc","badge":"picture","interactive":false},
  {"slug":"jee-pv-work-area","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nph-td-first-law","subtopicTitle":"Heat, Work and the First Law","conceptSlug":"nphtd-pv-work","conceptName":"Work as the area under a P-V graph","line":"When a gas pushes a piston out a little, the work it does is its pressure times the small change in volume. Add up all these small pieces as the gas expands and you get the area under its curve on a P-V graph. So a P-V graph turns work into geometry: a rectangle, a triangle or a trapezium.","pyqExampleId":"1c5cdf34-a02c-4f35-8161-9a87252420b3","badge":"picture","interactive":false},
  {"slug":"ht-pv-process-diagram","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"thermodynamics","chapterName":"Thermodynamics","subtopicSlug":"nph-td-processes","subtopicTitle":"Processes and Heat Engines","conceptSlug":"nphtd-processes","conceptName":"Isothermal, adiabatic, isochoric and isobaric processes","line":"Most questions fix one thing and let the rest change. Keep the temperature fixed and the process is isothermal; let no heat in or out and it is adiabatic; fix the volume and it is isochoric; fix the pressure and it is isobaric. Apply the first law to each, and each gets its own rule for work and heat.","pyqExampleId":"b1935b56-921c-4223-bfb4-a703fd26599f","badge":"picture","interactive":false},
  {"slug":"imat-boyle-curve","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"kinetic-theory","chapterName":"Kinetic Theory","subtopicSlug":"nph-kt-gas-laws","subtopicTitle":"Ideal Gas Laws","conceptSlug":"nphkt-gas-graphs","conceptName":"Boyle's and Charles's laws on a graph","line":"Hold one of P, V and T fixed and the ideal gas equation turns into a simple law between the other two. Each law has a shape on a graph, and NEET likes to give the graph and ask which line is at the higher pressure or temperature. The trick is always the same: fix one quantity by drawing a line across the graph, then compare the other.","pyqExampleId":"36821154-d116-41ed-aa3d-9cae09bbb46f","badge":"try","interactive":true},
  {"slug":"osc-shm-displacement-time","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"nph-os-equation","subtopicTitle":"SHM and Its Equation","conceptSlug":"nphos-equation","conceptName":"Displacement, amplitude, period and phase","line":"A motion that repeats itself after a fixed time is periodic. If it also goes to and fro about a mean position, it is an oscillation. Simple harmonic motion (SHM) is the simplest oscillation: the displacement is a sine (or cosine) of time. Picture a point going round a circle at a steady speed and look at its shadow on a diameter. The shadow moves to and fro in SHM, with the radius as its amplitude and the point's angular speed as its ω.","pyqExampleId":"7a721a30-a07a-4baa-b791-c338e74b4b47","badge":"picture","interactive":false},
  {"slug":"cet-shm-reference-circle","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"nph-os-equation","subtopicTitle":"SHM and Its Equation","conceptSlug":"nphos-motion","conceptName":"Velocity, acceleration and the test for SHM","line":"Differentiate the displacement and the velocity comes out as a cosine, a quarter cycle ahead. Differentiate again and the acceleration is minus ω² times the displacement: it always points back towards the mean position and grows with the distance from it. That is the test for SHM. If a body's acceleration is proportional to its displacement and opposite to it, the body does SHM.","pyqExampleId":"86bf9139-7d59-4ad4-9ec0-2525235e0630","badge":"try","interactive":true},
  {"slug":"osc-pendulum-restoring-force","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"nph-os-periods","subtopicTitle":"Springs and Pendulums","conceptSlug":"nphos-pendulum","conceptName":"The simple pendulum","line":"A small heavy bob on a light string swings about its lowest point. For small swings the pull of gravity back along the arc is about mgθ, which is proportional to the displacement, so the motion is SHM. The force constant works out as mg/L, and the mass cancels: the period depends only on the length and on g.","pyqExampleId":"fec2d11e-0ffb-4f4b-93c6-177c176cd106","badge":"picture","interactive":false},
  {"slug":"jee-shm-energy-graphs","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"oscillations","chapterName":"Oscillations","subtopicSlug":"nph-os-energy","subtopicTitle":"Energy in SHM","conceptSlug":"nphos-energy","conceptName":"Kinetic, potential and total energy","line":"A stretched spring stores potential energy, and the moving mass has kinetic energy. As the particle swings, energy passes from one form to the other, but with no friction the total stays the same. At the mean position it is all kinetic; at the extremes, where the particle stops for an instant, it is all potential.","pyqExampleId":"e85cacf3-a1b9-4ad6-86cd-6aa77d6dd34d","badge":"picture","interactive":false},
  {"slug":"cet-standing-wave-modes","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"waves","chapterName":"Waves","subtopicSlug":"nph-wv-standing","subtopicTitle":"Standing Waves and Pipes","conceptSlug":"nphwv-nodes","conceptName":"Counting nodes and antinodes","line":"Draw the standing wave and count. Each harmonic of a string or an open pipe adds one more half wavelength to the length, so one more loop. A closed pipe is built from quarter wavelengths, and only an odd number of them fits, so its harmonics go 1, 3, 5, ... and each step adds one node and one antinode. Counting is easy once you know what sits at each end.","pyqExampleId":"c4c725ba-87dd-4bfd-81e6-8f1a67563286","badge":"try","interactive":true},
  {"slug":"field-lines-charge","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electric-charges-and-fields","chapterName":"Electric Charges and Fields","subtopicSlug":"nph-ef-field","subtopicTitle":"Charge, Coulomb's Law and Electric Field","conceptSlug":"nphef-field","conceptName":"Electric field, field lines and charge density","line":"A charge changes the space around it, so that any other charge placed there feels a force. The electric field at a point is that force on each coulomb of a small positive test charge. Field lines draw the field: they leave positive charges, end on negative ones, and crowd together where the field is strong. When charge is spread over a wire or a surface, we describe it by how much charge sits on each metre or each square metre.","pyqExampleId":"597e49fb-24ea-4531-9cae-3706acf63a32","badge":"picture","interactive":false},
  {"slug":"cet-dipole-torque","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electric-charges-and-fields","chapterName":"Electric Charges and Fields","subtopicSlug":"nph-ef-dipole","subtopicTitle":"Electric Dipole","conceptSlug":"nphef-torque","conceptName":"Dipole in a uniform field: torque and energy","line":"In a uniform field the push on +q and the pull on −q are equal and opposite, so the dipole as a whole does not move. But the two forces act at different points, so they twist it, turning p to line up with E. Lined up with the field is the dipole's lowest energy; turned against the field is its highest, and turning it there takes work.","pyqExampleId":"a7d3df20-a3e6-4285-8df3-6949c7798ffe","badge":"try","interactive":true},
  {"slug":"neet-equipotentials","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electrostatic-potential","chapterName":"Electrostatic Potential and Capacitance","subtopicSlug":"nph-ep-energy","subtopicTitle":"Equipotentials and Potential Energy","conceptSlug":"nphep-equipotential","conceptName":"Equipotential surfaces and the field","line":"Join all the points that have the same potential and you get an equipotential surface. Moving a charge along it takes no work, so the field can have no part along the surface: it must cross it at right angles. The field always points downhill, from higher potential to lower, and it is strongest where the surfaces crowd together.","pyqExampleId":"a26f9115-e344-46e7-b10f-4ac00ece014e","badge":"picture","interactive":false},
  {"slug":"neet-capacitor-dielectric","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electrostatic-potential","chapterName":"Electrostatic Potential and Capacitance","subtopicSlug":"nph-ep-capacitance","subtopicTitle":"Capacitors and Dielectrics","conceptSlug":"nphep-dielectric","conceptName":"Dielectrics and dielectric constant","line":"A dielectric is an insulator. Put it in a field and its molecules line up a little as dipoles, leaving a thin layer of charge on each face that opposes the field. The field inside drops to E₀/K. Less field means less voltage for the same charge, so the capacitor holds more charge per volt: its capacitance rises.","pyqExampleId":"15d0282d-8427-4d20-84ec-fa1a9851aa13","badge":"try","interactive":true},
  {"slug":"resistance-wire-geometry","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"current-electricity","chapterName":"Current Electricity","subtopicSlug":"nph-ce-drift","subtopicTitle":"Current, Drift and Resistivity","conceptSlug":"nphce-resistivity","conceptName":"Resistance, resistivity and conductivity","line":"Resistance depends on the shape of a wire: longer means more resistance, thicker means less. Resistivity is the part that belongs to the material alone. A metal has a low resistivity because it has many free electrons and they travel a fair time between collisions. Conductivity is just the reverse of resistivity.","pyqExampleId":"000b3748-a1b6-4e16-98eb-099bb64c264e","badge":"picture","interactive":false},
  {"slug":"resistors-series-parallel","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"current-electricity","chapterName":"Current Electricity","subtopicSlug":"nph-ce-combinations","subtopicTitle":"Combinations of Resistors","conceptSlug":"nphce-series-parallel","conceptName":"Series and parallel combinations","line":"In series the same current must push through every resistor one after another, so the resistances add. In parallel each resistor offers a separate path for the same voltage, so adding a path always lowers the total. A useful check: a parallel total is smaller than the smallest resistor in it.","pyqExampleId":"27d6f3e1-5c67-40c7-8685-8e0abb775deb","badge":"picture","interactive":false},
  {"slug":"magnetic-force-triad","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"moving-charges-and-magnetism","chapterName":"Moving Charges and Magnetism","subtopicSlug":"nph-mc-force","subtopicTitle":"Magnetic Force on Charges and Wires","conceptSlug":"nphmc-lorentz","conceptName":"Magnetic force on a moving charge","line":"A magnetic field pushes only on charges that move, and it pushes sideways. The force is at right angles to both the velocity and the field. Because it is always sideways to the motion, it can turn a charge but never speed it up or slow it down.","pyqExampleId":"92f1c9cf-88c9-480a-8d32-a914fb946147","badge":"try","interactive":true},
  {"slug":"magnetic-field-around-wire","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"moving-charges-and-magnetism","chapterName":"Moving Charges and Magnetism","subtopicSlug":"nph-mc-ampere","subtopicTitle":"Ampere's Law, Solenoids and Parallel Wires","conceptSlug":"nphmc-ampere","conceptName":"Ampere's circuital law and the field of a straight wire","line":"Walk round any closed path and add up the field along your steps. Ampere's law says the total depends only on the current passing through the path, not on the shape of the path. Round a long straight wire the field is the same at every point of a circle, so the law gives the field in one line.","pyqExampleId":"8c74379c-7585-4dc9-8a6c-c579adac3256","badge":"picture","interactive":false},
  {"slug":"solenoid-field-lines","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"moving-charges-and-magnetism","chapterName":"Moving Charges and Magnetism","subtopicSlug":"nph-mc-ampere","subtopicTitle":"Ampere's Law, Solenoids and Parallel Wires","conceptSlug":"nphmc-solenoid","conceptName":"Field inside a long solenoid","line":"A solenoid is a long coil of many closely wound turns. Inside, the fields of all the turns point the same way along the axis and add up to a strong, uniform field. Outside, they nearly cancel. Only how tightly the turns are packed and the current matter, not how wide the coil is.","pyqExampleId":"3b7e6b9b-e51d-40fb-bf7c-bbdf958fdb38","badge":"picture","interactive":false},
  {"slug":"bar-magnet-field-lines","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"magnetism-and-matter","chapterName":"Magnetism and Matter","subtopicSlug":"nph-mm-dipole","subtopicTitle":"The Bar Magnet as a Dipole","conceptSlug":"nphmm-gauss","conceptName":"Gauss's law for magnetism","line":"Break a bar magnet in two and each piece has its own north and south pole: no one has ever found a pole on its own. So magnetic field lines never start or stop anywhere. They leave the north pole, go round outside, and come back through the inside of the magnet from south to north, closing on themselves. Every line that enters a closed surface must also leave it, so the net magnetic flux out of any closed surface is zero.","pyqExampleId":"76b0b9ad-11ba-452e-ab2a-2432ad952d98","badge":"picture","interactive":false},
  {"slug":"cet-lenz-magnet-coil","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electromagnetic-induction","chapterName":"Electromagnetic Induction","subtopicSlug":"nph-ei-faraday","subtopicTitle":"Induced EMF and Lenz's Law","conceptSlug":"nphei-lenz","conceptName":"Lenz's law and eddy currents","line":"The induced current always makes a field that fights the change in flux. Push a magnet towards a coil and the coil pushes back; pull it away and the coil pulls it back. This is energy conservation at work: you must do work against that opposing force, and the work turns into electrical energy. The same opposition acts inside a solid piece of metal, where the induced currents swirl round in loops called eddy currents.","pyqExampleId":"79dabdd3-9c37-410d-8637-5479f6c60420","badge":"try","interactive":true},
  {"slug":"cet-lcr-phasors","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"alternating-current","chapterName":"Alternating Current","subtopicSlug":"nph-ac-lcr","subtopicTitle":"Series LCR Circuit and Resonance","conceptSlug":"nphac-impedance","conceptName":"Impedance and phase angle","line":"In series the same current flows through R, L and C. The voltage across R is in step with it, the voltage across L is a quarter cycle ahead and the voltage across C a quarter cycle behind. So the L and C voltages point opposite ways and partly cancel. What is left adds to the resistor's voltage at right angles, like the two short sides of a right triangle. The total opposition of the circuit is its impedance.","pyqExampleId":"c82a108c-18ff-4c7c-8003-f198d076a753","badge":"try","interactive":true},
  {"slug":"cet-resonance-curve","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"alternating-current","chapterName":"Alternating Current","subtopicSlug":"nph-ac-lcr","subtopicTitle":"Series LCR Circuit and Resonance","conceptSlug":"nphac-resonance","conceptName":"Resonance in a series LCR circuit","line":"As the frequency rises, the inductor's reactance grows and the capacitor's falls. At one frequency the two are equal and cancel completely. Then only the resistor is left to oppose the current, so the impedance is the smallest it can be and the current the largest. This is resonance, and it is how a radio picks one station out of many.","pyqExampleId":"bbf19de1-60cc-4f3e-9b26-ec2e86ada5f6","badge":"try","interactive":true},
  {"slug":"neet-em-wave-fields","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"electromagnetic-waves","chapterName":"Electromagnetic Waves","subtopicSlug":"nph-em-waves","subtopicTitle":"Displacement Current and EM Waves","conceptSlug":"nphem-fields","conceptName":"Electric and magnetic fields of a plane wave","line":"In an electromagnetic wave an oscillating electric field and an oscillating magnetic field keep each other going. Both stand at right angles to each other and to the direction the wave moves, so the wave is transverse. They rise and fall together, and the electric field is always c times the magnetic field.","pyqExampleId":"3967d3d5-e6a8-40cb-bee3-d665ee5ec83f","badge":"picture","interactive":false},
  {"slug":"opt-concave-mirror-rays","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"ray-optics","chapterName":"Ray Optics and Optical Instruments","subtopicSlug":"nph-ro-reflection","subtopicTitle":"Reflection and Refraction","conceptSlug":"nphro-mirrors","conceptName":"Reflection and spherical mirrors","line":"Light bounces off a smooth surface at the same angle at which it arrives. A smooth surface keeps the rays in order, so they can meet again and form an image. A rough wall also reflects light, but scatters it in all directions, so it shows no image. A curved mirror is a small piece of a sphere: a concave mirror brings parallel rays together at its focus, a convex mirror spreads them out as if they came from a focus behind it.","pyqExampleId":"17fd806b-375d-4a2d-9305-74d2d77300e2","badge":"picture","interactive":false},
  {"slug":"opt-refraction-tir","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"ray-optics","chapterName":"Ray Optics and Optical Instruments","subtopicSlug":"nph-ro-reflection","subtopicTitle":"Reflection and Refraction","conceptSlug":"nphro-tir","conceptName":"Critical angle and total internal reflection","line":"Going from glass into air, light bends away from the normal. Tilt the ray more and more, and the refracted ray bends until it skims along the surface. That angle of incidence is the critical angle. Tilt any further and no light gets out at all: all of it is reflected back into the glass. This is total internal reflection.","pyqExampleId":"155698e3-af16-4086-b233-5f3ccfb476bd","badge":"picture","interactive":false},
  {"slug":"opt-convex-lens-rays","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"ray-optics","chapterName":"Ray Optics and Optical Instruments","subtopicSlug":"nph-ro-lenses","subtopicTitle":"Lenses","conceptSlug":"nphro-lens-formula","conceptName":"Thin lens formula and ray rules","line":"A lens is two curved refracting surfaces close together. A convex lens is thicker in the middle and brings parallel rays together at its focus. A concave lens is thinner in the middle and spreads them out, as if they came from a focus on the near side. The thin lens formula links where the object is, where the image is and the focal length, with the same sign rule as mirrors.","pyqExampleId":"fc57d7e5-5f5d-4dd8-8e5c-2c8fa4bb3efe","badge":"picture","interactive":false},
  {"slug":"neet-prism-deviation","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"ray-optics","chapterName":"Ray Optics and Optical Instruments","subtopicSlug":"nph-ro-prisms","subtopicTitle":"Prisms","conceptSlug":"nphro-deviation","conceptName":"Deviation and minimum deviation","line":"A prism bends a ray twice, once at each face, both times towards its base. The total turn is the angle of deviation. As the angle of incidence grows, the deviation first falls and then rises again, so there is one angle of incidence that gives the smallest deviation. At that point the ray passes through the prism symmetrically, and this is the easiest state in which to measure the glass's refractive index.","pyqExampleId":"90d70022-b408-494e-a266-6defc97f9bd8","badge":"try","interactive":true},
  {"slug":"cet-ydse-fringe-width","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"wave-optics","chapterName":"Wave Optics","subtopicSlug":"nph-wo-ydse","subtopicTitle":"Young's Double Slit Experiment","conceptSlug":"nphwo-fringe-width","conceptName":"Fringe width and fringe positions","line":"Two slits a distance d apart act as two coherent sources, and a screen sits a distance D away. A point at height y above the centre is a little nearer one slit than the other, and that extra path grows steadily with y. Each time it grows by one wavelength the light goes from bright to dark and back to bright, so the fringes are evenly spaced stripes.","pyqExampleId":"d1ba310b-c8a4-48a4-a00b-edb2f479d8ec","badge":"try","interactive":true},
  {"slug":"neet-brewster-angle","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"wave-optics","chapterName":"Wave Optics","subtopicSlug":"nph-wo-polarisation","subtopicTitle":"Diffraction and Polarisation","conceptSlug":"nphwo-brewster","conceptName":"Polarisation by reflection: Brewster's law","line":"Light reflected from glass or water is partly polarised. At one special angle of incidence it is completely polarised, and at that angle the reflected and refracted rays are exactly at right angles. The light that goes into the glass is only partly polarised.","pyqExampleId":"b8e5103b-2821-47df-bdf1-1bf66497d820","badge":"picture","interactive":false},
  {"slug":"cet-photoelectric-graphs","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"dual-nature","chapterName":"Dual Nature of Radiation and Matter","subtopicSlug":"nph-dn-photoelectric","subtopicTitle":"Photoelectric Effect","conceptSlug":"nphdn-photo-laws","conceptName":"What intensity and frequency change","line":"Shine light on a clean metal plate inside an evacuated tube and electrons fly out to a collector plate, making a photocurrent. Make the collector more positive and the current rises to a steady saturation value. Make it negative and fewer electrons reach it, until at the stopping potential even the fastest ones are turned back. Two things can be changed about the light, and they do different jobs: intensity sets how many electrons come out, frequency sets how fast the fastest ones are.","pyqExampleId":"6f6f8c64-0d79-47ee-be2e-95ffe9f57cae","badge":"picture","interactive":false},
  {"slug":"cet-hydrogen-series","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"atoms","chapterName":"Atoms","subtopicSlug":"nph-at-spectrum","subtopicTitle":"Hydrogen Spectrum","conceptSlug":"nphat-series","conceptName":"The spectral series of hydrogen","line":"All the lines that end on the same lower level make up one series, named after the scientist who found it. Lines ending on n = 1 are big jumps and lie in the ultraviolet; lines ending on n = 2 are the visible ones; lines ending on n = 3, 4 and 5 are small jumps and lie in the infrared. Learn the order of the lower levels, 1 to 5: Lyman, Balmer, Paschen, Brackett, Pfund.","pyqExampleId":"dd81ef39-20e5-44d1-8547-295a264dc197","badge":"picture","interactive":false},
  {"slug":"jee-binding-energy-curve","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"nuclei","chapterName":"Nuclei","subtopicSlug":"nph-nu-size","subtopicTitle":"Nuclear Size and Binding Energy","conceptSlug":"nphnu-mass-defect","conceptName":"Mass defect, binding energy and the nuclear force","line":"Weigh the free protons and neutrons, then weigh the nucleus they make: the nucleus is lighter. The missing mass left as energy when the nucleus formed, by E = mc². To pull the nucleus apart you must put that energy back. That energy is the binding energy, and the force that holds the nucleons together is the strong, short-range nuclear force.","pyqExampleId":"97046830-f8f6-4715-9383-77c292d104fb","badge":"picture","interactive":false},
  {"slug":"imat-half-life-decay","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"nuclei","chapterName":"Nuclei","subtopicSlug":"nph-nu-decay","subtopicTitle":"Radioactive Decay","conceptSlug":"nphnu-half-life","conceptName":"Half-life and activity","line":"Each nucleus decays at random, but in a large sample a fixed share decays every second. So the more nuclei there are, the more decay per second: the activity is proportional to the number left. In every half-life, half of the nuclei still present decay, so the amount left goes 1, 1/2, 1/4, 1/8 and so on. The activity falls on the same clock.","pyqExampleId":"f2edde36-e1e9-4896-a3be-c06aa384b204","badge":"try","interactive":true},
  {"slug":"cet-diode-bias","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"semiconductor-electronics","chapterName":"Semiconductor Electronics","subtopicSlug":"nph-se-junction","subtopicTitle":"Semiconductors and the p-n Junction","conceptSlug":"nphse-junction","conceptName":"The p-n junction and its bias","line":"When p-type meets n-type, electrons diffuse into the p-side and holes into the n-side, and they cancel near the joint. That leaves a thin depletion layer of fixed ions with a field across it, the barrier, which stops further diffusion. A battery that lowers the barrier (forward bias) lets a large current flow; one that raises it (reverse bias) lets only a tiny current through.","pyqExampleId":"3e60ee99-776f-4e74-99f2-f2d19442b00d","badge":"picture","interactive":false},
  {"slug":"cet-rectifier-waves","examSlug":"neet","examName":"NEET","subjectName":"Physics","subjectRoute":"neet-physics","subjectDisplay":"NEET Physics","chapterSlug":"semiconductor-electronics","chapterName":"Semiconductor Electronics","subtopicSlug":"nph-se-devices","subtopicTitle":"Rectifiers and Special Diodes","conceptSlug":"nphse-rectifier","conceptName":"Half-wave and full-wave rectifiers","line":"A diode lets current through one way only, so it can turn alternating current into current that flows one way. With one diode, only one half of each cycle gets through: a half-wave rectifier. With two diodes and a centre-tapped transformer, one diode conducts in each half, and both halves push current the same way through the load: a full-wave rectifier. The output still rises and falls, so a capacitor across the load is used to smooth it.","pyqExampleId":"9d46adb7-d4c8-49a9-9797-8fc295c2a183","badge":"try","interactive":true},
];

